### Instruction:
Change the code using decorator to log how long the function runs.

### Input:
def sum_function(a, b):
    return a + b

### Response:
import time

def log_time(func):
    def inner(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()

        print(f'Function {func.__name__} took {end-start} sec to run')

        return result
    return inner

@log_time
def sum_function(a, b):
    return a + b

