### Problem:
def intersection_of_sets(set1: set, set2: set) -> set:
    """
    Find the intersection of two sets using the OR operator.

    Args:
        set1: A set of elements.
        set2: Another set of elements.

    Returns:
        A set containing the intersection of elements from set1 and set2.

    Raises:
        TypeError: If either set1 or set2 is not a set.
    """

### Solution:

    if not isinstance(set1, set) or not isinstance(set2, set):
        raise TypeError("Both arguments must be sets.")

    return set(filter(lambda x: x in set2, set1))


# Example usage
set1 = {1, 2, 3, 4, 5}
set2 = {4, 5, 6, 7, 8}
print(intersection_of_sets(set1, set2))  # Output: {4, 5}

