def remove_intersection_duplicates(tuple1, tuple2):
    """Given two tuples, remove the duplicate elements present in both tuples and return the modified tuple."""

### Solution:

    intersection = set(tuple1).intersection(set(tuple2))
    return tuple(filter(lambda x: x not in intersection, tuple1)), tuple(filter(lambda x: x not in intersection, tuple2))

### Problem:
def sum_of_even_or_odd_numbers(numbers_list, even=True):
        """
        Return the sum of either even or odd numbers from a given list.

        Parameters:
        numbers_list (list): A list of integers.
        even (bool): Determines whether to consider even or odd numbers. Default is True (even).

        Returns:
        int: The sum of even or odd numbers from the given list.
        """

### Solution:

        if even:
            return sum(filter(lambda x: x % 2 == 0, numbers_list))
        else:
            return sum(filter(lambda x: x % 2 != 0, numbers_list))

